import{_ as t,o as d,c as o,a2 as a}from"./chunks/framework.BGlkWkwp.js";const w=JSON.parse('{"title":"TreeRow","description":"","frontmatter":{},"headers":[],"relativePath":"components/tree-row.md","filePath":"components/tree-row.md"}'),r={name:"components/tree-row.md"};function n(h,e,s,i,c,l){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="treerow" tabindex="-1">TreeRow <a class="header-anchor" href="#treerow" aria-label="Permalink to &quot;TreeRow&quot;">​</a></h1><p>TreeRow is one row of a <a href="./tree">Tree</a>: a <a href="./list-item">ListItem</a> indented by its depth, with a chevron, a name and actions.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it inside a Tree only. Pass <code>expandable</code> for a row with children and bind <code>expanded</code>, or handle <code>ontoggle</code> when the application keeps the state. Put the name, with a mark before it, in the children and the actions in <code>end</code>. In a tree that is reordered with <a href="./sortable">sortable</a>, pass <code>data-sortable-item</code> and <code>data-id</code> (and <code>data-kind</code>) to the row.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>depth</code></td><td><code>0</code></td><td>The depth, from 0</td></tr><tr><td><code>expandable</code></td><td><code>false</code></td><td>The row has children and shows the chevron</td></tr><tr><td><code>expanded</code></td><td><code>false</code></td><td>The children show (bindable)</td></tr><tr><td><code>ontoggle</code></td><td></td><td>Called with the new state when the chevron is pressed</td></tr><tr><td><code>grip</code></td><td><code>true</code></td><td>Shows the grip on hover (false where nothing is reordered)</td></tr><tr><td><code>gripShow</code></td><td><code>false</code></td><td>Always shows the grip, for screens without hover</td></tr><tr><td><code>sel</code></td><td><code>false</code></td><td>Selected</td></tr><tr><td><code>hidden</code></td><td><code>false</code></td><td>The row hides what it stands for: dimmed</td></tr><tr><td><code>dimmed</code></td><td><code>false</code></td><td>A parent is hidden: dimmed</td></tr><tr><td><code>dragging</code></td><td><code>false</code></td><td>The row is being dragged: dimmed</td></tr><tr><td><code>onclick</code></td><td></td><td>Called when the row is pressed</td></tr><tr><td><code>children</code></td><td>required</td><td>The name, and a mark before it</td></tr><tr><td><code>end</code></td><td></td><td>The actions on the right (a snippet)</td></tr></tbody></table><p>Other attributes (<code>data-*</code>, <code>aria-*</code>) go to the row.</p><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>The row is a ListItem: its height comes from its content, at least the tree&#39;s least height, and pad-md plus depth × pad-md on the left. Its columns are fixed: the chevron, the name, the kept actions. The chevron&#39;s place, the square of an icon button, is kept on a row that does not open, so nothing moves when a row gains children; a flat tree removes it. The name is one line, trimmed to its ink and clipped at the end of its column; a name in a <a href="./text">Text</a> with <code>clamp</code> ends with an ellipsis and shows in full on hover. The grip shows on hover and focus, gap-2xs left of the first thing the row shows, over the padding. Only an action marked <code>data-keep</code> (a state other than its default, such as a hidden eye) keeps a place: it always shows, at the right end, and its width is taken from the name. The other actions keep no place: on hover and focus they show over the end of the row, gap-sm before the kept ones, on an opaque ground (the panel under the row&#39;s own surface), and <code>data-open</code> on the row keeps them while a menu of the row is open: the row listens for the bubbling <code>kata-menu-toggle</code> event of a <a href="./dropdown">Dropdown</a> (and so a Kebab or a Popover) among its actions and has <code>data-open</code> while one is open. A selected row has the raise surface and a double blue line along its left edge; <code>hidden</code>, <code>dimmed</code> and <code>dragging</code> dim the row. A row with <code>onclick</code> is pressed with a click, Enter or Space; the right and left arrow keys open and close it, and the chevron never presses the row.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/tree-row/" title="TreeRow" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/tree-row/" target="_blank" rel="noopener">TreeRow</a></figcaption></figure>',11)])])}const m=t(r,[["render",n]]);export{w as __pageData,m as default};
